/**
 * The theme variant matrix for Eylül Güneş's projects.
 *
 * Every variant shares the base theme (@eylulg/ui/theme.css): the same type
 * scale, spacing, semantic tokens and status colours. A variant only changes
 * the brand hue, the gray family, the corner radius, the density and the font
 * tokens, so the apps feel related but not identical.
 *
 * The colour scales are generated by `npm run themes` (scripts/generate-themes.ts)
 * with fixed oklch lightness steps, so a given step has the same contrast in
 * every variant. The generated values live in ./scales.ts and in the published
 * CSS files at @eylulg/ui/themes/<name>.css.
 */
import { scales } from './scales';

export const variantNames = [
  'portfolio',
  'workspace',
  'review',
  'control-room',
  'watchlist',
  'tokens',
  'plain-language',
  'sudoku',
] as const;

export type VariantName = (typeof variantNames)[number];

export type GrayFamily = 'cool' | 'neutral' | 'zinc' | 'warm';
export type Radius = 'small' | 'medium' | 'large';
export type Density = 'compact' | 'comfortable';

/** The steps of every generated colour scale. */
export const scaleSteps = [
  '25',
  '50',
  '100',
  '200',
  '300',
  '400',
  '500',
  '600',
  '700',
  '800',
  '900',
  '950',
] as const;

export type ScaleStep = (typeof scaleSteps)[number];
export type ColorScale = Record<ScaleStep, string>;

export interface BrandSpec {
  /** Human name of the hue, such as "indigo". */
  name: string;
  /** oklch hue angle in degrees. */
  hue: number;
  /** Peak oklch chroma, reached at step 500. Clamped to sRGB per step. */
  chroma: number;
}

export interface GraySpec {
  family: GrayFamily;
  /** Closest Tailwind gray, for orientation. */
  like: 'slate' | 'neutral' | 'zinc' | 'stone';
  hue: number;
  chroma: number;
}

export interface VariantSpec {
  name: VariantName;
  /** The project this variant is designed for. */
  project: string;
  description: string;
  brand: BrandSpec;
  gray: GraySpec;
  radius: Radius;
  density: Density;
  fonts: {
    display: string;
    mono: string;
    /** Font for data surfaces (table cells, stat values): sans or mono. */
    data: 'sans' | 'mono';
  };
  /**
   * Optional dark mode overrides of semantic tokens, as raw CSS values. Used
   * by control-room for a darker operations surface.
   */
  dark?: Partial<Record<'bg-primary' | 'bg-secondary' | 'bg-elevated', string>>;
}

export interface Variant extends VariantSpec {
  colors: { brand: ColorScale; gray: ColorScale };
}

/** Inter for every variant keeps the family coherent. */
export const displayFont =
  "'Inter', ui-sans-serif, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif";

/** A system monospace stack: no web font download, native look on every OS. */
export const monoFont =
  "ui-monospace, SFMono-Regular, 'SF Mono', Menlo, Monaco, Consolas, 'Liberation Mono', 'Courier New', monospace";

