/**
 * Builds the CSS for one variant. `selector` is where the light values apply;
 * the published files use `:root, [data-ui-variant='<name>']`.
 */
export function variantCss(
  variant: Variant,
  selector = `:root,\n[data-ui-variant='${variant.name}']`,
): string {
  const lines: string[] = [];
  for (const step of scaleSteps)
    lines.push(`  --color-brand-${step}: ${variant.colors.brand[step]};`);
  for (const step of scaleSteps)
    lines.push(`  --color-gray-${step}: ${variant.colors.gray[step]};`);
  for (const [key, value] of Object.entries(radii[variant.radius])) {
    lines.push(`  --radius-${key}: ${value};`);
  }
  for (const [key, value] of Object.entries(densities[variant.density])) {
    lines.push(`  --density-${key}: ${value};`);
  }
  lines.push(`  --font-display: ${variant.fonts.display};`);
  lines.push(`  --font-mono: ${variant.fonts.mono};`);
  lines.push(`  --ui-font-data: var(--font-${variant.fonts.data === 'mono' ? 'mono' : 'sans'});`);

  let css = `${selector} {\n${lines.join('\n')}\n}\n`;
  if (variant.dark) {
    const darkSelector = selector
      .split(',')
      .map((part) => part.trim())
      .flatMap((part) =>
        part === ':root'
          ? [':root.dark', ':root.dark-mode']
          : [`.dark ${part}`, `.dark-mode ${part}`, `${part}.dark`, `${part}.dark-mode`],
      )
      .join(',\n');
    const darkLines = Object.entries(variant.dark).map(
      ([token, value]) => `  --ui-${token}: ${value};`,
    );
    css += `\n${darkSelector} {\n${darkLines.join('\n')}\n}\n`;
  }
  return css;
}

export function variantFileCss(variant: Variant): string {
  return [
    '/*',
    ` * @eylulg/ui theme variant: ${variant.name} (${variant.project})`,
    ` * ${variant.description}`,
    ` * Brand ${variant.brand.name}, gray ${variant.gray.like}, radius ${variant.radius}, density ${variant.density}.`,
    ' *',
    ' * Import after @eylulg/ui/theme.css. Generated by `npm run themes`; do not edit by hand.',
    ' */',
    '',
    variantCss(variant),
  ].join('\n');
}
